/* ================================================
   简单点顶栏定制 - 保留原背景图
================================================ */

/* 顶栏容器 - 悬浮定位保留背景图 */
.chat-header-custom {
  /* 悬浮定位 */
  position: fixed !important;
  top: 12px !important;        /* 可调整上下位置，修改此值即可移动 */
  left: 0 !important;
  right: 0 !important;
  z-index: 1000 !important;

  /* 圆角设置：左上角和右上角*/
  border-radius: 50px 50px 0 0 !important;

  /* 背景：毛玻璃效果 */
  background: rgba(255, 255, 255, 1) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(180%) !important;

  /* 内边距与高度 */
  padding: 8px 16px !important;
  min-height: 56px !important;

  /* 保留背景图片（原有图片在伪元素中，确保不被覆盖） */
  overflow: visible !important;
}

/* 保留原有的背景图片（通过伪元素） */
.chat-header-custom::before {
  content: '' !important;
  position: absolute !important;
  top: -200px !important;
  left: 0 !important;
  right: 0 !important;
  width: 100% !important;
  height: 250px !important;
  background: url('https://i.postimg.cc/d1W9FJWB/IMG_2216.jpg') no-repeat center top !important;    /* 换背景🩶 */
  background-size: cover !important;
  border-radius: 30px 30px 0 0 !important;
  pointer-events: none !important;
  z-index: -2 !important;
}

/* 白色背景层（半透明，让背景图透出） */
.chat-header-custom::after {
  content: '' !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  background: rgba(255, 255, 255, 1) !important;  /* 保留背景图可见 */
  border-radius: 30px 30px 0 0 !important;
  z-index: -1 !important;
  pointer-events: none !important;
}

/* ========== 消息区域偏移，避免被顶栏遮挡 ========== */
.chat-messages-area {
  padding-top: calc(12px + 56px + 12px) !important;  /* 顶部间距 + 顶栏高度 + 额外间距 */
}

/* 兼容 safe-area（刘海屏） */
@supports (padding-top: env(safe-area-inset-top)) {
  .chat-header-custom {
    top: calc(12px + env(safe-area-inset-top)) !important;
  }
  .chat-messages-area {
    padding-top: calc(12px + 56px + env(safe-area-inset-top) + 12px) !important;
  }
}

/* ========== 去掉顶栏底部分割线 ========== */
.chat-header-custom {
  border-bottom: none !important;
  border-bottom-width: 0 !important;
  border-bottom-style: none !important;
  box-shadow: none !important;
}

/* ========== 返回按钮：保持原样，不做替换 ========== */
